"""Actual eight HTTP/native associations; FIFO engine is not parallel compute."""
import hashlib,json,math,struct
from pathlib import Path
from serial37_canonical_json_v3 import canonical
from source43_api_baseline_profile_v1 import require,ALIAS
import source43_api_baseline_client_v1 as client
from c1_trace_contract import completion_facts,trace_end_accepted

def epoch(v):require(type(v)in(int,float)and math.isfinite(v)and v>0,'Finite actual epoch required');return v
def ids(v):require(type(v)is list and v and all(type(t)is int and 0<=t<248320 for t in v),'Typed native vocabulary IDs required');return v
def digest(v):return hashlib.sha256(b''.join(struct.pack('<I',t)for t in ids(v))).hexdigest()
def bind(root):
    root=Path(root);report=json.loads((root/'api-client/report.json').read_text());require(report['passed']is True and report['errors']==[]and len(report['results'])==8,'All eight actual HTTP replies required');require(report['models']==json.loads((root/'api-client/models.json').read_text())and [r['id']for r in report['models']['data']]==['hotschmoe-dd',ALIAS],'Original actual served IDs required')
    raw=(root/'engine-token-trace.jsonl').read_bytes();require(raw.endswith(b'\n'),'Complete native trace lines required');trace=[json.loads(line)for line in raw.splitlines()];require(all(r['kind']in('engine_begin','engine_end','engine_close')for r in trace),'Foreign native trace kind');begins=[r for r in trace if r['kind']=='engine_begin'];ends=[r for r in trace if r['kind']=='engine_end'];closes=[r for r in trace if r['kind']=='engine_close'];require(len(begins)==len(ends)==8 and len(closes)==1,'Exact eight GEN and one original close required');require([r['call']for r in begins]==list(range(1,9))and len({r['call']for r in ends})==8 and {r['call']for r in ends}==set(range(1,9)),'Exact unique original native call roster required');pids={r['engine_pid']for r in trace};require(len(pids)==1 and all(type(p)is int and p>0 for p in pids),'One actual native owner required')
    pending=list(range(8));pairs=[]
    for b in begins:
        e=next(e for e in ends if e['call']==b['call']);require(epoch(b['epoch'])<=epoch(e['epoch'])and b['rendered_matches_submitted']is True and b['embeddings']is None and type(b['max_new'])is int and b['max_new']==64,'Exact native submitted prompt/budget required');require(digest(b['submitted_ids'])==b['submitted_ids_sha256']==b['rendered_prompt']['sha256']and b['rendered_prompt']['ids']==b['submitted_ids'],'Original rendered/submitted bytes differ');require(digest(e['generated_ids'])==e['generated_ids_sha256']and len(e['generated_ids'])<=64,'Generated bytes/budget differ');require(trace_end_accepted(e)and canonical(completion_facts(e['engine_done'],e['generated_ids'],len(b['submitted_ids']),b['pinned_eos_ids'],True,False))==canonical({k:e[k]for k in completion_facts(e['engine_done'],e['generated_ids'],len(b['submitted_ids']),b['pinned_eos_ids'],True,False)}),'Original fresh DONE consumption facts differ');require(e['done_observation']['call']==b['call']and e['done_observation']['done']==e['engine_done'],'Actual thread-local DONE ownership differs')
        matches=[i for i in pending if report['results'][i]['request']['messages']==b['rendered_prompt']['messages']];require(matches,'Native prompt has no HTTP owner');i=min(matches);pending.remove(i);row=report['results'][i];case=client.CASES[i]if i<6 else client.CASES[(i-6)*2];packet=client.body(i,case[1]);require(canonical(row['request'])==canonical(packet)==canonical(json.loads((root/('api-client/request-'+str(i)+'.json')).read_text())),'Actual submitted HTTP body changed');response=json.loads((root/('api-client/response-'+str(i)+'.json')).read_text());require(canonical(response)==canonical(row['response'])and response['model']==packet['model'],'Actual response/model changed');client.response_gate(response,case[2]);require(response['usage']['prompt_tokens']==len(b['submitted_ids'])and response['usage']['completion_tokens']==len(e['generated_ids'])and response['choices'][0]['finish_reason']==e['engine_done']['finish'],'API/native token counts or finish differ');require(b['sampling'].get('temperature')==0 and b['rendered_prompt']['template_kwargs']=={'enable_thinking':False},'Deterministic native/template policy differs');pairs.append({'HTTP_index':i,'call':b['call'],'submitted_ids_sha256':b['submitted_ids_sha256'],'generated_ids_sha256':e['generated_ids_sha256']})
    for x,y in((0,4),(2,5),(0,6),(2,7)):
        px=next(p for p in pairs if p['HTTP_index']==x);py=next(p for p in pairs if p['HTTP_index']==y);require(px['submitted_ids_sha256']==py['submitted_ids_sha256']and px['generated_ids_sha256']==py['generated_ids_sha256'],'Actual repeat/concurrent native IDs differ')
    a,b=report['results'][6:];require(all(type(r[k])is int and r[k]>0 for r in(a,b)for k in('started_monotonic_ns','finished_monotonic_ns'))and all(r['started_monotonic_ns']<r['finished_monotonic_ns']for r in(a,b))and max(r['started_monotonic_ns']for r in(a,b))<min(r['finished_monotonic_ns']for r in(a,b)),'Two actual client lifetimes must overlap');close=closes[0];require(close['clean_exit']is True and type(close['exit_code'])is int and close['exit_code']==0 and close['error']is None and epoch(close['epoch'])>=max(e['epoch']for e in ends),'Actual native close required');return {'passed':True,'actual_requests':8,'actual_HTTP_overlap_passed':True,'native_computation_parallelism_qualified':False,'engine_pid':next(iter(pids)),'pairs':pairs,'trace_sha256':hashlib.sha256(raw).hexdigest(),'native_closed_epoch':close['epoch']}
